const imageId = $json.image;

let imageUrl = null;

if (imageId) {
  imageUrl = `https://down-vn.img.susercontent.com/file/${imageId}`;
}

return [{
  json: {
    ...$json,
    image_url: imageUrl
  }
}];

const product = $('Parse Product').first().json;
const affiliate = $('Request Aff link').first().json;

return [{
  json: {
    product_name: product.product_name,
    price: product.price,
    original_price: product.original_price,
    currency: product.currency,
    rating: product.rating,
    description: product.description,
    attributes: product.attributes,
    variants: product.variants,
    affiliate_url: affiliate.affiliate_url
  }
}];

const response = $json.data?.data;

if (!response) {
  throw new Error('Không tìm thấy data.data trong response Shopee');
}

const item = response.item;

if (!item) {
  throw new Error('Không tìm thấy item trong response Shopee');
}

// Lấy các model có giá
const models = Array.isArray(item.models) ? item.models : [];

const prices = models
  .map(m => Number(m.price))
  .filter(p => Number.isFinite(p) && p > 0);

const originalPrices = models
  .map(m => Number(m.price_before_discount))
  .filter(p => Number.isFinite(p) && p > 0);

// Giá nhỏ nhất
const minPrice = prices.length
  ? Math.min(...prices) / 100000
  : null;

const minOriginalPrice = originalPrices.length
  ? Math.min(...originalPrices) / 100000
  : null;

// Danh sách biến thể
const variants = models.map(m => ({
  name: m.name ?? null,
  price: Number.isFinite(Number(m.price))
    ? Number(m.price) / 100000
    : null,
  original_price: Number.isFinite(Number(m.price_before_discount))
    ? Number(m.price_before_discount) / 100000
    : null,
  model_id: m.model_id ?? null,
  stock: m.stock ?? null,
  sold: m.sold ?? null,
}));

return [{
  json: {
    product_url: $('Edit Fields').first().json.product_url,

    shop_id: String(item.shop_id),
    item_id: String(item.item_id),

    product_name: item.title ?? null,

    price: minPrice,
    original_price: minOriginalPrice,

    rating: item.item_rating?.rating_star ?? null,

    currency: item.currency ?? 'VND',

    image: item.image ?? null,

    shop_location: item.shop_location ?? null,

    brand: item.brand ?? null,

    category_id: item.cat_id ?? null,

    description: item.description ?? null,

    attributes: item.attributes ?? [],

    variants,

    variant_count: variants.length,

    status: item.item_status ?? null
  }
}];
